1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"os/exec"
10		"strings"
11	
12		"github.com/go-git/go-git/v6/plumbing"
13		"github.com/spf13/cobra"
14	
15		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
16		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
17		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
18		"github.com/entireio/cli/cmd/entire/cli/gitremote"
19		"github.com/entireio/cli/cmd/entire/cli/gitrepo"
20		"github.com/entireio/cli/internal/coreapi"
21	)
22	
23	// explainRepoRef is a parsed `explain --repo` value: either an owner/name slug
24	// (possibly given with a gh/ prefix) or a raw repo ULID that still needs a
25	// control-plane lookup to become owner/name.
26	type explainRepoRef struct {
27		owner, repo string // owner/name form (lowercased)
28		repoID      string // bare-ULID form
29	}
30	
31	// parseExplainRepoFlag parses the --repo flag value. Accepted shapes:
32	// `owner/name`, `gh/owner/name` (leading slash optional), or a bare repo ULID.
33	// owner/name reuse the GitHub charset validation of the mirror clone-ref
34	// parser and come back lowercased, matching what the control plane persists.
35	func parseExplainRepoFlag(value string) (explainRepoRef, error) {
36		v := strings.TrimSpace(value)
37		if v == "" {
38			return explainRepoRef{}, errors.New("--repo requires a value: owner/name, gh/owner/name, or a repo ID")
39		}
40		if strings.Contains(v, "/") {
41			// Normalize owner/name to the gh/owner/name clone-ref shape so
42			// parseMirrorCloneRef's charset validation applies to both forms.
43			ref := strings.TrimPrefix(v, "/")
44			if !strings.HasPrefix(ref, "gh/") {
45				ref = "gh/" + ref
46			}
47			_, owner, repo, err := parseMirrorCloneRef(ref)
48			if err != nil {
49				return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID: %w", value, err)
50			}
51			return explainRepoRef{owner: owner, repo: repo}, nil
52		}
53		if !looksLikeULID(v) {
54			return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID (ULID)", value)
55		}
56		return explainRepoRef{repoID: v}, nil
57	}
58	
59	// resolveExplainRepoID resolves a raw repo ULID to its owner/name via the
60	// control plane's by-id lookup (the same call `entire repo get <ulid>` uses).
61	// A clusterFlag naming a cluster in a different federation dials that
62	// cluster's core instead of the active context's, matching how the placement
63	// lookup routes (see listPullablePlacements).
64	func resolveExplainRepoID(cmd *cobra.Command, repoID, clusterFlag string) (owner, repo string, err error) {
65		runWithCore, err := coreRunnerForCluster(clusterFlag)
66		if err != nil {
67			return "", "", err
68		}
69		var fullName string
70		err = runWithCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
71			r, err := c.GetRepo(ctx, coreapi.GetRepoParams{RepoId: repoID})
72			if err != nil {
73				if isCoreNotFound(err) {
74					return fmt.Errorf("no repository with ID %q visible from your login", repoID)
75				}
76				return fmt.Errorf("look up repository %q: %w", repoID, err)
77			}
78			fullName = r.FullName.Or("")
79			return nil
80		})
81		if err != nil {
82			return "", "", err
83		}
84		owner, repo, ok := strings.Cut(strings.ToLower(fullName), "/")
85		if !ok || owner == "" || repo == "" {
86			return "", "", fmt.Errorf("repository %q has an unexpected full name %q (want owner/name)", repoID, fullName)
87		}
88		return owner, repo, nil
89	}
90	
91	// explainRepoIsCurrent reports whether owner/repo names the same repository as
92	// the cwd worktree's origin remote (handles ssh, https, and entire:// mirror
93	// URL forms). --repo is GitHub-scoped (gh/owner/name), so a non-GitHub origin
94	// with a coincidentally matching owner/name must not count as the current
95	// repo. Best-effort: any lookup or parse failure returns false, so explain
96	// proceeds with the cross-repo fetch path.
97	func explainRepoIsCurrent(ctx context.Context, owner, repo string) bool {
98		curForge, curOwner, curRepo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
99		if err != nil || curForge != "gh" {
100			return false
101		}
102		return strings.EqualFold(curOwner, owner) && strings.EqualFold(curRepo, repo)
103	}
104	
105	// resolveExplainRepoFetchURL resolves the entire:// mirror URL to fetch a
106	// foreign repo's checkpoint ref from: pullable placements via the core API
107	// (the same authority `repo clone` uses), then the shared placement picker
108	// with explain-specific wording and the --cluster escape hatch.
109	func resolveExplainRepoFetchURL(cmd *cobra.Command, owner, repo, clusterFlag string) (string, error) {
110		placements, err := listPullablePlacements(cmd, owner, repo, clusterFlag)
111		if err != nil {
112			return "", err
113		}
114		if len(placements) == 0 {
115			return "", fmt.Errorf("no mirror found for /gh/%s/%s; cross-repo explain fetches checkpoints from the repo's Entire mirror", owner, repo)
116		}
117		chosen, err := selectPlacement(cmd, placements, clusterFlag, placementPicker{
118			selector: "--cluster",
119			title:    "This repo is mirrored on more than one cluster — pick one to fetch the checkpoint from",
120			action:   "Explain",
121		})
122		if err != nil {
123			return "", err
124		}
