126		// URL like a user-supplied --cluster, so apply the same anti-token-leak
127		// guard before building it (see repo clone).
128		if err := validateClusterHost(chosen.ClusterHost); err != nil {
129			return "", fmt.Errorf("mirror has an invalid cluster host %q: %w", chosen.ClusterHost, err)
130		}
