134	// crossRepoExplainRequest carries the explain flag values the cross-repo
135	// dispatch needs, so maybeRunCrossRepoExplain can live outside the already
136	// maintidx-capped newExplainCmd closure.
137	type crossRepoExplainRequest struct {
