173			})
174		}
175		defer func() { _ = lookup.Close() }()
176		// --generate/--force are mutually exclusive with --repo, so this is
177		// always a read-only render (generate=false, force=false, timeout 0).
178		return true, runExplainCheckpointWithLookup(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), target,
179			req.noPager, !req.short, req.full, req.rawTranscript, false, false, req.searchAll, lookup, nil, 0)
180	}
181	
182	// openCrossRepoExplain resolves --repo/--cluster and, when the target repo
183	// differs from the cwd repo, fetches the checkpoint's per-checkpoint ref from
184	// that repo's Entire mirror into a throwaway temp repo and returns an explain
185	// lookup over it — a pure lookup that never writes a ref, object, or config
186	// entry into the cwd repo, so a foreign checkpoint can never join (or count
187	// as) the local checkpoint namespace. cleanup removes the temp repo; the
188	// caller owns closing the lookup before running cleanup. When --repo names
189	// the cwd repo both returns are nil and the caller falls through to the
190	// normal local flow (behavior identical to no flag).
191	func openCrossRepoExplain(cmd *cobra.Command, repoFlag, clusterFlag, target string) (lookup *explainCheckpointLookup, cleanup func(), err error) {
192		ref, err := parseExplainRepoFlag(repoFlag)
193		if err != nil {
194			return nil, nil, err
195		}
196		// Everything past flag parsing is a runtime failure (network, git), not a
