198		cmd.SilenceUsage = true
199		owner, repoName := ref.owner, ref.repo
200		if ref.repoID != "" {
201			owner, repoName, err = resolveExplainRepoID(cmd, ref.repoID, clusterFlag)
202			if err != nil {
