204			}
205		}
206		if explainRepoIsCurrent(cmd.Context(), owner, repoName) {
207			return nil, nil, nil
208		}
209		// A prefix cannot name a per-checkpoint ref, so cross-repo needs the full ID.
210		cid, err := id.NewCheckpointID(target)
211		if err != nil {
212			return nil, nil, fmt.Errorf("--repo requires a full checkpoint ID (12-char hex or 26-char ULID); a prefix cannot be resolved cross-repo: %w", err)
213		}
214		url, err := resolveExplainRepoFetchURL(cmd, owner, repoName, clusterFlag)
215		if err != nil {
216			return nil, nil, err
217		}
218		return fetchCrossRepoCheckpoint(cmd.Context(), cmd.ErrOrStderr(), url, owner+"/"+repoName, cid)
219	}
