227		refName, err := checkpoint.RefName(cid)
228		if err != nil {
229			// Defensive only: cid is already validated by the caller.
230			return nil, nil, err //nolint:wrapcheck // RefName's error is self-describing
231		}
232		tmpDir, err := os.MkdirTemp("", "entire-explain-repo-")
233		if err != nil {
