237		lookup, err := fetchCrossRepoCheckpointInto(ctx, errW, tmpDir, url, ownerRepo, cid, refName)
238		if err != nil {
239			cleanup()
240			return nil, nil, err
241		}
242		return lookup, cleanup, nil
243	}
244	
245	// fetchCrossRepoCheckpointInto initializes a repo in tmpDir, fetches the
246	// checkpoint ref into it, and builds the explain lookup over it.
247	func fetchCrossRepoCheckpointInto(ctx context.Context, errW io.Writer, tmpDir, url, ownerRepo string, cid id.CheckpointID, refName plumbing.ReferenceName) (*explainCheckpointLookup, error) {
